import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    cost = [int(x) for x in data[2:2 + n]]
    pos = 2 + n
    best = {}
    for i in range(n):
        mask = 0
        for j in range(m):
            if data[pos + i * m + j] == '1':
                mask |= 1 << j
        if mask and (mask not in best or cost[i] < best[mask]):
            best[mask] = cost[i]
    size = 1 << m
    INF = float('inf')
    dp = [INF] * size
    dp[0] = 0
    for mask, c in best.items():
        for s in range(size):
            v = dp[s] + c
            t = s | mask
            if v < dp[t]:
                dp[t] = v
    ans = dp[size - 1]
    print(-1 if ans == INF else ans)

