best = -1
for sel in range(1 << n):
    covered = [False] * m
    tot = 0
    for i in range(n):
        if sel >> i & 1:
            tot += cost[i]
            for j in range(m):
                if rows[i][j]:
                    covered[j] = True
    if all(covered) and (best == -1 or tot < best):
        best = tot
